query aggregateRadarDetections($environmentId: String!, $timeRange: AggregateRadarDetectionsTimeRange) {
  environment(id: $environmentId) {
    aggregateRadarDetections(timeRange: $timeRange) {
      totalDetections
      totalDetectionsDelta
      allowed
      allowedDelta
      blocked
      blockedDelta
      challenged
      challengedDelta
      data {
        timestamp
